def compare_lengths(ages):
    list_len = len(ages)
    set_len = len(set(ages))
    if list_len > set_len:
        bigger = 'list'
    elif set_len > list_len:
        bigger = 'set'
    else:
        bigger = 'equal'
    return (list_len, set_len, bigger)
